 if(c.method.equals("writeWorkspace")){String s=(String)c.arguments;if(s.length()>40*1024*1024)throw new IOException("Workspace size limit reached");AtomicFile f=new AtomicFile(new File(getFilesDir(),"workspace-v2.json"));FileOutputStream out=null;try{out=f.startWrite();out.write(s.getBytes(java.nio.charset.StandardCharsets.UTF_8));f.finishWrite(out);}catch(Exception ex){if(out!=null)f.failWrite(out);throw ex;}r.success(null);return;}
 if(c.method.equals("takePhoto")||c.method.equals("scanQr")){if(pending!=null)throw new IOException("Finish the current action first.");pending=r;if(c.method.equals("scanQr")){action="scan";permission();}else new AlertDialog.Builder(this).setTitle("Equipment evidence").setItems(new String[]{"Take a photo","Choose from gallery"},(d,i)->{if(i==0){action="camera";permission();}else{cameraUri=null;try{startActivityForResult(new Intent(Intent.ACTION_GET_CONTENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE),702);}catch(Exception ex){fail("Image picker unavailable.");}}}).setOnCancelListener(d->done(null)).show();return;}
