 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==701){if(g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)launch();else fail("Camera permission declined.");}}
